<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Requests\{UpdateRequestStatusRequest,AssignRequestRequest};use App\Models\Request as LeadRequest;use App\Services\RequestManagementService;use Illuminate\Http\Request;
class AdminRequestController extends ApiController{public function __construct(private RequestManagementService $service){}public function index(Request $r){$this->admin($r);return $this->success(LeadRequest::with(['service','provider','assignments'])->latest()->paginate(20));}public function show(Request $r,LeadRequest $lead){$this->admin($r);return $this->success($lead->load(['service','provider','assignments.admin']));}public function status(UpdateRequestStatusRequest $req,LeadRequest $lead){$this->admin($req);return $this->success($this->service->status($lead,$req->validated()['status']));}public function assign(AssignRequestRequest $req,LeadRequest $lead){$this->admin($req);return $this->success($this->service->assign($lead,$req->user(),$req->validated()));}private function admin(Request $r){abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);}}
